const item = $input.first().json;
const first = (item['First Name'] || '').trim();
const last = (item['Last Name'] || '').trim();
const email = (item['Personal/Contact Email'] || '').trim();
const jobTitle = item['Job Title'] || '';
const department = item['Department'] || '';
const groupsRaw = item['Groups to assign'] || '';

const localPart = email.split('@')[0].toLowerCase().replace(/[^a-z0-9.]/g, '');
const mailNickname = localPart || (first + last).toLowerCase().replace(/[^a-z0-9.]/g, '');
// TODO: replace YOUR-TENANT with your real verified domain (or *.onmicrosoft.com) once your tenant exists
const userPrincipalName = `${mailNickname}@YOUR-TENANT.onmicrosoft.com`;

function genPassword(len) {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789!@#%^&*';
  let pw = '';
  for (let i = 0; i < len; i++) pw += chars[Math.floor(Math.random() * chars.length)];
  return pw;
}

const groups = groupsRaw.split(',').map(g => g.trim()).filter(Boolean);

return [{
  json: {
    displayName: `${first} ${last}`.trim(),
    mailNickname,
    userPrincipalName,
    tempPassword: genPassword(16),
    jobTitle,
    department,
    groups,
  }
}];

const newUser = $input.first().json;
const groups = $('Build User Payload').first().json.groups;
return groups.map(g => ({ json: { groupId: g, userId: newUser.id } }));

const created = $('Create User').first().json;
const groupResults = $('Assign Group').all().map(i => i.json);
return [{
  json: {
    newUserId: created.id,
    userPrincipalName: created.userPrincipalName,
    displayName: created.displayName,
    groupsAssigned: groupResults.length,
    timestamp: new Date().toISOString(),
  }
}];
